  @protected
  LocateOutcome dco_decode_locate_outcome(dynamic raw) {
    // Codec=Dco (DartCObject based), see doc to use other codecs
    switch (raw[0]) {
      case 0:
        return LocateOutcome_Located(
          location: dco_decode_box_autoadd_file_location_view(raw[1]),
        );
      case 1:
        return LocateOutcome_Outside();
      case 2:
        return LocateOutcome_Failed();
      default:
        throw Exception("unreachable");
    }
  }

  @protected
  MergeQueueView dco_decode_merge_queue_view(dynamic raw) {
    // Codec=Dco (DartCObject based), see doc to use other codecs
    final arr = raw as List<dynamic>;
    if (arr.length != 3)
      throw Exception('unexpected arr length: expect 3 but see ${arr.length}');
    return MergeQueueView(
