  @protected
  void sse_encode_activity_intent(
    ActivityIntent self,
    SseSerializer serializer,
  ) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    switch (self) {
      case ActivityIntent_SetConnected(connected: final connected):
        sse_encode_i_32(0, serializer);
        sse_encode_bool(connected, serializer);
      case ActivityIntent_Watch(chat: final chat, token: final token):
        sse_encode_i_32(1, serializer);
        sse_encode_box_autoadd_chat_ref_view(chat, serializer);
        sse_encode_CastedPrimitive_u_64(token, serializer);
      case ActivityIntent_Release(token: final token):
        sse_encode_i_32(2, serializer);
        sse_encode_CastedPrimitive_u_64(token, serializer);
      case ActivityIntent_Load(chat: final chat):
        sse_encode_i_32(3, serializer);
        sse_encode_box_autoadd_chat_ref_view(chat, serializer);
      case ActivityIntent_SetHookPaused(
        chat: final chat,
        hookKey: final hookKey,
        paused: final paused,
      ):
        sse_encode_i_32(4, serializer);
        sse_encode_box_autoadd_chat_ref_view(chat, serializer);
        sse_encode_String(hookKey, serializer);
        sse_encode_bool(paused, serializer);
      case ActivityIntent_RunPr(
        chat: final chat,
        action: final action,
        repoId: final repoId,
        identity: final identity,
        confirmUnresolvedComments: final confirmUnresolvedComments,
      ):
        sse_encode_i_32(5, serializer);
        sse_encode_box_autoadd_chat_ref_view(chat, serializer);
        sse_encode_pr_action_kind(action, serializer);
        sse_encode_opt_String(repoId, serializer);
        sse_encode_opt_box_autoadd_pr_identity_view(identity, serializer);
        sse_encode_bool(confirmUnresolvedComments, serializer);
      case ActivityIntent_WatchDiff(target: final target, token: final token):
        sse_encode_i_32(6, serializer);
        sse_encode_box_autoadd_diff_target_view(target, serializer);
        sse_encode_CastedPrimitive_u_64(token, serializer);
      case ActivityIntent_ReleaseDiff(token: final token):
        sse_encode_i_32(7, serializer);
        sse_encode_CastedPrimitive_u_64(token, serializer);
      case ActivityIntent_RefreshDiff(target: final target):
        sse_encode_i_32(8, serializer);
        sse_encode_box_autoadd_diff_target_view(target, serializer);
      case ActivityIntent_Close():
        sse_encode_i_32(9, serializer);
    }
  }

