  @protected
  void sse_encode_auth_session(AuthSession self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    switch (self) {
      case AuthSession_SignedIn(field0: final field0):
        sse_encode_i_32(0, serializer);
        sse_encode_box_autoadd_signed_in_view(field0, serializer);
      case AuthSession_SignedOut():
        sse_encode_i_32(1, serializer);
    }
  }

  @protected
  void sse_encode_auth_status(AuthStatus self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    switch (self) {
      case AuthStatus_SignedIn(field0: final field0):
        sse_encode_i_32(0, serializer);
        sse_encode_box_autoadd_signed_in_view(field0, serializer);
      case AuthStatus_Unverified(lastUserJson: final lastUserJson):
        sse_encode_i_32(1, serializer);
        sse_encode_opt_String(lastUserJson, serializer);
      case AuthStatus_SignedOut():
        sse_encode_i_32(2, serializer);
    }
  }

