        sse_encode_i_32(0, serializer);
        sse_encode_String(computerId, serializer);
        sse_encode_String(code, serializer);
      case BridgeEvent_Message(
        computerId: final computerId,
        messageJson: final messageJson,
      ):
        sse_encode_i_32(1, serializer);
        sse_encode_String(computerId, serializer);
        sse_encode_String(messageJson, serializer);
      case BridgeEvent_Closed(
        computerId: final computerId,
        code: final code,
        reason: final reason,
      ):
        sse_encode_i_32(2, serializer);
        sse_encode_String(computerId, serializer);
        sse_encode_String(code, serializer);
        sse_encode_String(reason, serializer);
      case BridgeEvent_RelayOpened(peersJson: final peersJson):
        sse_encode_i_32(3, serializer);
        sse_encode_String(peersJson, serializer);
      case BridgeEvent_RelayClosed(reason: final reason):
        sse_encode_i_32(4, serializer);
        sse_encode_String(reason, serializer);
      case BridgeEvent_Peers(peersJson: final peersJson):
        sse_encode_i_32(5, serializer);
        sse_encode_String(peersJson, serializer);
    }
  }

