  @protected
  void sse_encode_feed_row(FeedRow self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    switch (self) {
      case FeedRow_Message(
        uid: final uid,
        results: final results,
        streamingSpinner: final streamingSpinner,
        parts: final parts,
      ):
        sse_encode_i_32(0, serializer);
        sse_encode_CastedPrimitive_u_64(uid, serializer);
        sse_encode_opt_box_autoadd_results_ref(results, serializer);
        sse_encode_bool(streamingSpinner, serializer);
        sse_encode_bool(parts, serializer);
      case FeedRow_Run(
        runKey: final runKey,
        steps: final steps,
        shownFrom: final shownFrom,
        expanded: final expanded,
        results: final results,
        anchorMessageId: final anchorMessageId,
      ):
        sse_encode_i_32(1, serializer);
        sse_encode_String(runKey, serializer);
        sse_encode_list_step_ref(steps, serializer);
        sse_encode_u_32(shownFrom, serializer);
        sse_encode_bool(expanded, serializer);
        sse_encode_box_autoadd_results_ref(results, serializer);
        sse_encode_opt_String(anchorMessageId, serializer);
      case FeedRow_Steps(
        turnKey: final turnKey,
        counts: final counts,
        expanded: final expanded,
        timer: final timer,
      ):
        sse_encode_i_32(2, serializer);
        sse_encode_String(turnKey, serializer);
        sse_encode_list_step_count_view(counts, serializer);
        sse_encode_bool(expanded, serializer);
        sse_encode_opt_box_autoadd_timer_view(timer, serializer);
      case FeedRow_Timer(turnKey: final turnKey, timer: final timer):
        sse_encode_i_32(3, serializer);
        sse_encode_opt_String(turnKey, serializer);
        sse_encode_opt_box_autoadd_timer_view(timer, serializer);
      case FeedRow_TurnFooter(turnKey: final turnKey):
        sse_encode_i_32(4, serializer);
        sse_encode_String(turnKey, serializer);
      case FeedRow_ResponseActions(
        uid: final uid,
        turnKey: final turnKey,
        atMessageId: final atMessageId,
      ):
        sse_encode_i_32(5, serializer);
        sse_encode_CastedPrimitive_u_64(uid, serializer);
        sse_encode_String(turnKey, serializer);
        sse_encode_String(atMessageId, serializer);
    }
  }

