  @protected
  void sse_encode_home_intent(HomeIntent self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    switch (self) {
      case HomeIntent_LoadOptions(workspaceId: final workspaceId):
        sse_encode_i_32(0, serializer);
        sse_encode_String(workspaceId, serializer);
      case HomeIntent_Choices(context: final context):
        sse_encode_i_32(1, serializer);
        sse_encode_String(context, serializer);
      case HomeIntent_SaveChoices(
        context: final context,
        choices: final choices,
      ):
        sse_encode_i_32(2, serializer);
        sse_encode_String(context, serializer);
        sse_encode_box_autoadd_home_choices_view(choices, serializer);
      case HomeIntent_Drafts():
        sse_encode_i_32(3, serializer);
      case HomeIntent_SetDraft(context: final context, text: final text):
        sse_encode_i_32(4, serializer);
        sse_encode_String(context, serializer);
        sse_encode_String(text, serializer);
      case HomeIntent_FlushDrafts():
        sse_encode_i_32(5, serializer);
      case HomeIntent_Close():
        sse_encode_i_32(6, serializer);
      case HomeIntent_Inventory(model: final model, inventory: final inventory):
        sse_encode_i_32(7, serializer);
        sse_encode_CastedPrimitive_u_64(model, serializer);
        sse_encode_box_autoadd_home_inventory_view(inventory, serializer);
      case HomeIntent_Load(model: final model):
        sse_encode_i_32(8, serializer);
        sse_encode_CastedPrimitive_u_64(model, serializer);
      case HomeIntent_RefreshChoices(model: final model):
        sse_encode_i_32(9, serializer);
        sse_encode_CastedPrimitive_u_64(model, serializer);
      case HomeIntent_Select(model: final model, pick: final pick):
        sse_encode_i_32(10, serializer);
        sse_encode_CastedPrimitive_u_64(model, serializer);
        sse_encode_box_autoadd_home_pick(pick, serializer);
      case HomeIntent_Unmount(model: final model):
        sse_encode_i_32(11, serializer);
