  @protected
  void sse_encode_pipelines_intent(
    PipelinesIntent self,
    SseSerializer serializer,
  ) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    switch (self) {
      case PipelinesIntent_SetConnected(connected: final connected):
        sse_encode_i_32(0, serializer);
        sse_encode_bool(connected, serializer);
      case PipelinesIntent_Watch(chat: final chat, token: final token):
        sse_encode_i_32(1, serializer);
        sse_encode_box_autoadd_chat_ref_view(chat, serializer);
        sse_encode_CastedPrimitive_u_64(token, serializer);
      case PipelinesIntent_Release(token: final token):
        sse_encode_i_32(2, serializer);
        sse_encode_CastedPrimitive_u_64(token, serializer);
      case PipelinesIntent_Load(chat: final chat):
        sse_encode_i_32(3, serializer);
        sse_encode_box_autoadd_chat_ref_view(chat, serializer);
      case PipelinesIntent_Get(chat: final chat, id: final id):
        sse_encode_i_32(4, serializer);
        sse_encode_box_autoadd_chat_ref_view(chat, serializer);
        sse_encode_String(id, serializer);
      case PipelinesIntent_Log(
        chat: final chat,
        id: final id,
        jobId: final jobId,
        stepId: final stepId,
      ):
        sse_encode_i_32(5, serializer);
        sse_encode_box_autoadd_chat_ref_view(chat, serializer);
        sse_encode_String(id, serializer);
        sse_encode_String(jobId, serializer);
        sse_encode_String(stepId, serializer);
      case PipelinesIntent_ClearLogSelection(chat: final chat, id: final id):
        sse_encode_i_32(6, serializer);
        sse_encode_box_autoadd_chat_ref_view(chat, serializer);
        sse_encode_String(id, serializer);
      case PipelinesIntent_Control(
        chat: final chat,
        id: final id,
        action: final action,
      ):
        sse_encode_i_32(7, serializer);
        sse_encode_box_autoadd_chat_ref_view(chat, serializer);
        sse_encode_String(id, serializer);
        sse_encode_pipeline_action(action, serializer);
      case PipelinesIntent_ClearActionError(chat: final chat, id: final id):
        sse_encode_i_32(8, serializer);
        sse_encode_box_autoadd_chat_ref_view(chat, serializer);
        sse_encode_String(id, serializer);
      case PipelinesIntent_Form(
        chat: final chat,
        pipelineId: final pipelineId,
        origin: final origin,
      ):
        sse_encode_i_32(9, serializer);
        sse_encode_box_autoadd_chat_ref_view(chat, serializer);
        sse_encode_String(pipelineId, serializer);
        sse_encode_pipeline_origin(origin, serializer);
      case PipelinesIntent_Start(
        chat: final chat,
        pipelineId: final pipelineId,
        origin: final origin,
        inputs: final inputs,
      ):
        sse_encode_i_32(10, serializer);
        sse_encode_box_autoadd_chat_ref_view(chat, serializer);
        sse_encode_String(pipelineId, serializer);
        sse_encode_pipeline_origin(origin, serializer);
        sse_encode_list_pipeline_input_value(inputs, serializer);
      case PipelinesIntent_Content(
        chat: final chat,
        id: final id,
        source: final source,
      ):
        sse_encode_i_32(11, serializer);
        sse_encode_box_autoadd_chat_ref_view(chat, serializer);
        sse_encode_String(id, serializer);
        sse_encode_box_autoadd_pipeline_content_source(source, serializer);
      case PipelinesIntent_Follow(
        token: final token,
        chat: final chat,
        online: final online,
      ):
        sse_encode_i_32(12, serializer);
        sse_encode_CastedPrimitive_u_64(token, serializer);
        sse_encode_opt_box_autoadd_chat_ref_view(chat, serializer);
        sse_encode_bool(online, serializer);
      case PipelinesIntent_Unfollow(token: final token):
        sse_encode_i_32(13, serializer);
        sse_encode_CastedPrimitive_u_64(token, serializer);
      case PipelinesIntent_DrawerUpdate(
        token: final token,
        chat: final chat,
        online: final online,
        ready: final ready,
      ):
        sse_encode_i_32(14, serializer);
        sse_encode_CastedPrimitive_u_64(token, serializer);
        sse_encode_box_autoadd_chat_ref_view(chat, serializer);
        sse_encode_bool(online, serializer);
        sse_encode_bool(ready, serializer);
      case PipelinesIntent_DrawerRetry(token: final token):
        sse_encode_i_32(15, serializer);
        sse_encode_CastedPrimitive_u_64(token, serializer);
      case PipelinesIntent_DrawerAct(
        token: final token,
        itemId: final itemId,
        action: final action,
        notifySubscriber: final notifySubscriber,
      ):
        sse_encode_i_32(16, serializer);
        sse_encode_CastedPrimitive_u_64(token, serializer);
        sse_encode_String(itemId, serializer);
        sse_encode_work_action(action, serializer);
        sse_encode_bool(notifySubscriber, serializer);
      case PipelinesIntent_DrawerClose(token: final token):
        sse_encode_i_32(17, serializer);
        sse_encode_CastedPrimitive_u_64(token, serializer);
      case PipelinesIntent_Close():
        sse_encode_i_32(18, serializer);
    }
  }

