  @protected
  void sse_encode_projects_intent(
    ProjectsIntent self,
    SseSerializer serializer,
  ) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    switch (self) {
      case ProjectsIntent_Discover():
        sse_encode_i_32(0, serializer);
      case ProjectsIntent_Commit(
        discovery: final discovery,
        url: final url,
        allowed: final allowed,
      ):
        sse_encode_i_32(1, serializer);
        sse_encode_CastedPrimitive_u_64(discovery, serializer);
        sse_encode_String(url, serializer);
        sse_encode_bool(allowed, serializer);
      case ProjectsIntent_ReadBack():
        sse_encode_i_32(2, serializer);
      case ProjectsIntent_Acknowledge(jobId: final jobId):
        sse_encode_i_32(3, serializer);
        sse_encode_String(jobId, serializer);
      case ProjectsIntent_Dismiss(jobId: final jobId):
        sse_encode_i_32(4, serializer);
        sse_encode_String(jobId, serializer);
      case ProjectsIntent_Retire(projectIds: final projectIds):
        sse_encode_i_32(5, serializer);
        sse_encode_list_String(projectIds, serializer);
      case ProjectsIntent_Close():
        sse_encode_i_32(6, serializer);
    }
  }

